async function retry(fn, maxAttempts = 3) {
  let lastErr;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastErr = err;
      await sleep(100 * 2 ** (attempt - 1));
    }
  }
  throw lastErr;
}

