package tests

import (
	"testing"
	"time"

	"example.com/acme/internal/cache"
)

func TestCacheExpiry(t *testing.T) {
	c := cache.New(50 * time.Millisecond)
	c.Set("k", []byte("v"))
	time.Sleep(60 * time.Millisecond)
	if _, ok := c.Get("k"); ok {
		t.Fatal("expected expired key to be gone")
	}
}

func TestCacheExpiryZeroTTL(t *testing.T) {
	c := cache.New(0)
	c.Set("k", []byte("v"))
	if _, ok := c.Get("k"); ok {
		t.Fatal("zero TTL must expire immediately")
	}
}

func TestCacheExpiryRefresh(t *testing.T) {
	c := cache.New(100 * time.Millisecond)
	c.Set("k", []byte("v"))
	c.Set("k", []byte("v"))
	time.Sleep(30 * time.Millisecond)
	if _, ok := c.Get("k"); !ok {
		t.Fatal("refreshed key must still be live")
	}
}

